	('539532da-e238-4c53-8533-94fe266e7d01', 'Tom', 'Davis', 'Former secondary school science teacher with 15 years in the classroom. Taught eight years in a bilingual science program. 25 plus years in EdTech Sales. Serve on many nonprofit boards and committees.', '15 years of teaching Life Science, Biology, Earth Science and Spanish 1 & 2. Basketball Coach and grant administrator.', '{Biology,"Life Science","Earth Science","Spanish 1 & 2"}', '{"CA Single Subject Life Science Teaching Credential"}', NULL, '2025-04-01 02:44:03.452853+00', '2025-05-06 16:39:59.583919+00', '{"{\"name\": \"Former Secondary School Biology Teacher\", \"status\": \"active\"}","{\"name\": \"Interested in anything STEAM related; how students acquire language and students with learning disabilities.\", \"status\": \"active\"}","{\"name\": \"EdTech enthusiast.\", \"status\": \"active\"}","{\"name\": \"Champion of the education nonprofit\", \"status\": \"active\"}"}', 'tomdavis70@gmail.com', '{"chat_notifications": true}', NULL, NULL, 'active', NULL, true, NULL, '{"sms": false, "email": true, "in_app": true}', false, NULL, NULL, NULL, false, NULL, NULL),
