INSERT INTO "public"."journey_reminder_templates" ("id", "stage", "reminder_type", "subject", "content", "cta_text", "cta_url", "active", "created_at", "updated_at") VALUES
	('de45cab5-fa43-404d-abb3-c52727ff1b53', 'new', '24h', 'Start your sideby journey today', 'Complete your reflection to unlock personalized learning connections. It only takes a few minutes!', 'Complete Reflection', '/dashboard', true, '2025-05-06 16:39:59.583919+00', '2025-05-06 16:39:59.583919+00'),
	('2d2066f7-f3a8-4277-8e04-c01c7750e192', 'new', '48h', 'Reminder: Your sideby reflection is waiting', 'Your reflection is the first step to meaningful connections with other educators. Take a moment to complete it now.', 'Start Now', '/dashboard', true, '2025-05-06 16:39:59.583919+00', '2025-05-06 16:39:59.583919+00'),
	('7f8ca067-0ed8-4c3c-9940-4c98f7267111', 'new', 'weekly', 'Don''t miss out on sideby connections', 'Many educators are finding value in sideby connections. Start by completing your reflection to join them.', 'Complete Reflection', '/dashboard', true, '2025-05-06 16:39:59.583919+00', '2025-05-06 16:39:59.583919+00'),
	('90174025-eed6-44de-a928-885988b6d7b8', 'reflection_completed', '24h', 'Your sideby profile is ready for matching', 'Thanks for completing your reflection! We''re working on finding you a great match based on your preferences.', 'View Dashboard', '/dashboard', true, '2025-05-06 16:39:59.583919+00', '2025-05-06 16:39:59.583919+00'),
	('e9eef71b-bf31-4fdf-8933-66b4b6bf47e9', 'reflection_completed', '48h', 'Still looking for your perfect match', 'Your profile is in our matching queue. While you wait, you can explore learning ideas in the dashboard.', 'Explore Ideas', '/dashboard?tab=ideas', true, '2025-05-06 16:39:59.583919+00', '2025-05-06 16:39:59.583919+00'),
	('f1d6181d-1603-4633-89a8-916c6851d56f', 'reflection_completed', 'weekly', 'Update on your sideby matching status', 'We''re still working to find you the perfect learning partner. Check your dashboard for updates.', 'Check Status', '/dashboard', true, '2025-05-06 16:39:59.583919+00', '2025-05-06 16:39:59.583919+00'),
	('06589fa0-48ec-47ac-95e8-0b945f150deb', 'matched', '24h', 'You have a new learning connection!', 'Great news! You''ve been matched with another educator. Schedule a time to meet and start learning together.', 'Schedule Now', '/dashboard?tab=match', true, '2025-05-06 16:39:59.583919+00', '2025-05-06 16:39:59.583919+00'),
	('3dc4a5fa-9a47-4d4c-bbf4-29d8e349f91f', 'matched', '48h', 'Reminder: Schedule time with your match', 'Don''t forget to schedule a time to connect with your match. It''s quick and easy!', 'Schedule Meeting', '/dashboard?tab=match', true, '2025-05-06 16:39:59.583919+00', '2025-05-06 16:39:59.583919+00'),
	('b3771058-7311-4d2e-89b0-2bc99485ffd0', 'matched', 'weekly', 'Your match is waiting to connect', 'Your sideby match is still waiting to hear from you. Schedule a quick meeting to start your learning conversation.', 'Schedule Now', '/dashboard?tab=match', true, '2025-05-06 16:39:59.583919+00', '2025-05-06 16:39:59.583919+00'),
	('0a5b3cfe-6e18-45bd-aa74-493d6e2d3339', 'scheduled', '24h', 'Your sideby meeting is coming up', 'You have a scheduled meeting with your match. Prepare by reviewing the suggested topics.', 'View Details', '/dashboard?tab=match', true, '2025-05-06 16:39:59.583919+00', '2025-05-06 16:39:59.583919+00'),
	('e069915d-c9a9-4f1e-ab4b-d2be7a60298e', 'scheduled', '48h', 'Getting ready for your sideby meeting', 'Your scheduled meeting is approaching. Take a moment to think about what you hope to learn.', 'Meeting Details', '/dashboard?tab=match', true, '2025-05-06 16:39:59.583919+00', '2025-05-06 16:39:59.583919+00'),
	('717ebdff-0ebe-4589-a778-209a4f9c0785', 'scheduled', 'weekly', 'Don''t forget your scheduled sideby meeting', 'Your learning connection is waiting to meet with you. Make sure to attend your scheduled meeting.', 'Check Schedule', '/dashboard?tab=match', true, '2025-05-06 16:39:59.583919+00', '2025-05-06 16:39:59.583919+00'),
	('9ba0b378-a207-4407-b100-6f6fa1540eb6', 'conversation', '24h', 'Share what you learned in your sideby conversation', 'Now that you''ve had your conversation, share your key insights or questions with the community.', 'Share Ideas', '/dashboard?tab=ideas', true, '2025-05-06 16:39:59.583919+00', '2025-05-06 16:39:59.583919+00'),
	('f0cb95e7-be41-4574-a0ab-5d41579319dc', 'conversation', '48h', 'Reminder: Document your learning insights', 'Don''t forget to capture your learning from your recent conversation. Your insights can help others!', 'Record Insights', '/dashboard?tab=ideas', true, '2025-05-06 16:39:59.583919+00', '2025-05-06 16:39:59.583919+00'),
	('cf7a879e-6645-4e1a-918a-92114496bf94', 'conversation', 'weekly', 'Your learning journey continues', 'Take your learning further by recording insights from your conversation and exploring new ideas.', 'Explore Ideas', '/dashboard?tab=ideas', true, '2025-05-06 16:39:59.583919+00', '2025-05-06 16:39:59.583919+00');


