	('939ed8ad-9954-4161-bdeb-b7b713249c0a', 'ad34b8fc-781f-4c46-b547-012480e87e9f', 'f03cab9c-eb51-4a96-9b3f-2e39b9a3491f', 'Hopping on Upduo now.', '2025-02-13 21:37:49.254245+00', '2025-02-13 21:37:49.254245+00', 'user', NULL),
