	('4834fd54-4887-489f-9b7a-af9695571efb', 'e5a67ee9-d30e-4f26-bafd-bf20b9ba4ab6', '138357', '"[{\"speaker\":\"12022\",\"text\":\"Hi, everybody.\",\"startTime\":1745902985,\"endTime\":1745902986},{\"speaker\":\"12022\",\"text\":\"My name is Mike and as an educator I''m helping build side by and I teach high school math. \",\"startTime\":1745902986,\"endTime\":1745902992},{\"speaker\":\"12022\",\"text\":\"I hope to learn about.\",\"startTime\":1745902992,\"endTime\":1745902994},{\"speaker\":\"12022\",\"text\":\"I have to teach.\",\"startTime\":1745903000,\"endTime\":1745903001},{\"speaker\":\"12022\",\"text\":\"My stance with respect to teaching and learning is a forward stance, leaning forward new ideas that make it better. \",\"startTime\":1745903017,\"endTime\":1745903023},{\"speaker\":\"12022\",\"text\":\"Pushing students to skip steps whenever possible.\",\"startTime\":1745903025,\"endTime\":1745903028},{\"speaker\":\"12022\",\"text\":\"We got a lot to learn trying to go fast.\",\"startTime\":1745903028,\"endTime\":1745903030},{\"speaker\":\"12022\",\"text\":\"Right now I''m having fun.\",\"startTime\":1745903043,\"endTime\":1745903044},{\"speaker\":\"12022\",\"text\":\"Building I''m like writing code.\",\"startTime\":1745903045,\"endTime\":1745903047},{\"speaker\":\"12022\",\"text\":\"So that''s new for me. I find that it''s not. Yeah, that''s my.\",\"startTime\":1745903048,\"endTime\":1745903050},{\"speaker\":\"12022\",\"text\":\"I can get lost in that. I do it late on Monday nights.\",\"startTime\":1745903051,\"endTime\":1745903054}]"', '2025-04-30 20:57:08.842379+00', '2025-04-30 20:57:08.842379+00', '{"type": "SINGLE", "duration": 57, "created_at": "2025-04-30T20:57:08.811Z", "session_title": "Welcome to sideby!", "knowledgeNodes": [{"id": "22", "name": "Welcome to sideby!", "tags": [{"name": "Active"}, {"name": "ColumbiaSelkirk"}, {"name": "Leaders of Color"}]}], "manually_stored": true}'),
